const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
const sandbox={console,Intl,Date};sandbox.window=sandbox;sandbox.globalThis=sandbox;vm.createContext(sandbox);
for(const file of ['data.js','clinical-model-v2.js','clinical-addons.js','clinical-library-v3.js','exercise-intelligence-knee.js','exercise-intelligence-next.js','exercise-quality.js','exercise-graph.js','core.js','planner.js','progression-engine.js','progression-examples.js'])vm.runInContext(fs.readFileSync(path.join(__dirname,'../../reda-2',file),'utf8'),sandbox);
const E=sandbox.RedaProgression,X=sandbox.RedaProgressionExamples,copy=x=>JSON.parse(JSON.stringify(x)),fixture=(scenario='ready',profile='daily')=>copy(X.scenario(X.example(profile),scenario));
test('three different goal/capacity profiles execute the same kernel with distinct exercise choices',()=>{const variants=new Set();for(const p of ['daily','hyrox','strength']){const i=fixture('ready',p),before=JSON.stringify(i),r=E.evaluate(i);assert.equal(r.action,'advance');assert.equal(r.mayApply,false);assert.equal(r.mode,'simulation-only');assert.equal(JSON.stringify(i),before);variants.add(i.plan.exercises.map(x=>x.id+'.'+x.variantId).join(','))}assert.equal(variants.size,3)});
test('one easy session cannot unlock a step',()=>{const i=fixture('single');i.observations[0].effort='easy';assert.equal(E.evaluate(i).code,'evidence')});
test('multiple sessions on one day count as one training day',()=>{const i=fixture();i.observations.forEach(r=>{r.completedAt=i.observations[0].completedAt;r.respondedAt=i.observations[0].respondedAt});const r=E.evaluate(i);assert.equal(r.code,'evidence');assert.equal(r.metrics.successfulDays,1)});
test('missing next-day response waits, and same-day or future response cannot satisfy it',()=>{assert.equal(E.evaluate(fixture('missing')).code,'response');for(const time of ['2026-09-02T20:00:00Z','2027-01-01T10:00:00Z']){const i=fixture();i.observations[0].respondedAt=time;assert.equal(E.evaluate(i).code,'data')}});
test('changed symptoms take precedence over missing response or heavy earlier sessions',()=>{for(const first of ['unknown','settled']){const i=fixture();i.observations[0].nextDay=first;i.observations[0].effort='heavy';i.observations[2].nextDay='worse';assert.equal(E.evaluate(i).action,'review')}});
test('reported deterioration takes precedence even when recovery is low or unknown',()=>{for(const recovery of ['low','unknown']){const i=fixture('worse');i.context.recovery=recovery;i.context.otherTraining='high';assert.equal(E.evaluate(i).action,'review')}});
test('excess training load, low recovery and difficulty prevent increases',()=>{for(const [s,code] of [['load','load'],['low','recovery'],['heavy','difficult']])assert.equal(E.evaluate(fixture(s)).code,code)});
test('missing context is not treated as readiness',()=>{const i=fixture();delete i.context.recovery;assert.equal(E.evaluate(i).code,'context');i.context.recovery='ready';delete i.context.concern;assert.equal(E.evaluate(i).code,'context')});
test('request for contact, changed environment and unresolved review suppress progression',()=>{for(const field of ['reviewRequested','environmentChanged']){const i=fixture();i.context[field]=true;assert.equal(E.evaluate(i).action,'review')}const i=fixture();i.state.reviewPending=true;assert.equal(E.evaluate(i).action,'review')});
test('open sessions never receive another prescription',()=>{const r=E.evaluate(fixture('open'));assert.equal(r.code,'openSession');assert.equal(r.previewPlan,undefined)});
test('prescription, environment and policy revision mismatch fail closed',()=>{for(const mutate of [i=>i.plan.exercises[0].dose.reps++,i=>i.plan.context.equipment='gym',i=>i.state.policyRevision++,i=>i.plan.schedule.days.push(6)]){const i=fixture();mutate(i);assert.equal(E.evaluate(i).code,'version')}});
test('data from other policies, revisions and steps never supplies missing evidence',()=>{for(const key of ['policyId','policyRevision','stepId']){const i=fixture();i.observations[0][key]=key==='policyRevision'?999:'other';assert.equal(E.evaluate(i).code,'evidence')}});
test('duplicate deliveries are idempotent and conflicting rows block',()=>{const i=fixture(),first=E.evaluate(i);i.observations.push(copy(i.observations[0]));assert.equal(E.evaluate(i).transitionKey,first.transitionKey);assert.equal(E.evaluate(i).evidenceIds.length,3);i.observations.at(-1).effort='heavy';assert.equal(E.evaluate(i).code,'conflict')});
test('future, malformed and stale data cannot advance the plan',()=>{for(const date of ['2026-02-30T10:00:00Z','2028-01-01T10:00:00Z','not-a-date']){const i=fixture();i.observations[0].completedAt=date;assert.equal(E.evaluate(i).code,'data')}const i=fixture();i.now='2026-10-20T10:00:00Z';assert.equal(E.evaluate(i).code,'evidence')});
test('partial and skipped activity are distinct from successfully completed training',()=>{for(const status of ['partial','skipped']){const i=fixture();i.observations[0].status=status;assert.equal(E.evaluate(i).code,'difficult')}});
test('elapsed time alone never advances; actual observation days still matter',()=>{const i=fixture();i.observations=[];assert.equal(E.evaluate(i).code,'evidence');const j=fixture();j.policy.rules.minDaysAtStep=12;assert.equal(E.evaluate(j).code,'time')});
test('expiry requires a new frame and does not imply rehabilitation is finished',()=>{const i=fixture();i.now='2026-12-01T12:00:00Z';assert.equal(E.evaluate(i).code,'expired');assert.equal(E.evaluate(i).previewPlan,undefined)});
test('next step resets required evidence and can only advance adjacently',()=>{const i=fixture(),r=E.evaluate(i);assert.equal(r.targetStepId,'step-1');i.plan=r.previewPlan;i.state={...i.state,stepId:r.targetStepId,startedAt:i.now};i.now='2026-09-20T12:00:00Z';assert.equal(E.evaluate(i).code,'evidence')});
test('a fully evaluated final step ends the frame without invented extra dosage',()=>{const model=X.example('daily');model.plan=model.policy.steps[2].plan;model.state.stepId='step-2';const r=E.evaluate(X.scenario(model,'ready'));assert.equal(r.action,'complete');assert.equal(r.previewPlan,undefined)});
test('malformed frames, empty defaults and clinically identical steps are rejected',()=>{for(const change of [p=>p.rules.minSuccessfulDays=0,p=>p.rules.acceptedEffort=['heavy'],p=>p.steps[1].id=p.steps[0].id,p=>p.steps[1].plan=copy(p.steps[0].plan),p=>p.steps[1].plan.context.equipment='other',p=>p.steps[0].plan.exercises[0].dose.sets=Infinity]){const p=fixture().policy;change(p);assert.throws(()=>E.compile(p))}const p=fixture().policy;p.steps[1].plan=copy(p.steps[0].plan);p.steps[1].plan.exercises[0].editedByClinician=true;assert.throws(()=>E.compile(p))});
test('no flags can enable application; explain-only model contract carries no patient identity',()=>{const i=fixture();i.policy.mode='live';assert.equal(E.evaluate(i).action,'blocked');i.policy=E.compile(i.policy);assert.equal(i.policy.mode,'simulation-only');const brief=E.explanationBrief(E.evaluate(i));assert.ok(brief.restrictions.length);assert.equal(brief.plan,undefined);assert.equal(brief.patientName,undefined)});
